import{_ as n,o,c as i,a2 as a}from"./chunks/framework.BfI5QxtK.js";const h=JSON.parse('{"title":"Config API","description":"","frontmatter":{},"headers":[],"relativePath":"config.md","filePath":"config.md"}'),t={name:"config.md"};function s(c,e,l,r,d,g){return o(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="config-api" tabindex="-1">Config API <a class="header-anchor" href="#config-api" aria-label="Permalink to &quot;Config API&quot;">​</a></h1><p>Use <a href="/gnoblin/config/configure"><code>gnoblin.configure</code></a> for settings, named shortcuts and autostart commands. The reference pages list the supported fields and defaults.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h2><ul><li><a href="/gnoblin/config/configure"><code>gnoblin.configure</code></a> — set compositor, shell, input and window-management options.</li><li><a href="/gnoblin/config/window_rule"><code>gnoblin.window_rule</code></a> — add a window or layer-surface rule.</li><li><a href="/gnoblin/config/permission_rule"><code>gnoblin.permission_rule</code></a> — add a portal permission rule.</li><li><a href="/gnoblin/config/animation"><code>gnoblin.animation</code></a> — register a named animation.</li><li><a href="/gnoblin/config/config"><code>gnoblin.config</code></a> — inspect or edit the config assembled during loading.</li><li><a href="/gnoblin/config/load"><code>gnoblin.load</code></a> — load another Lua config file.</li><li><a href="/gnoblin/config/snapshot"><code>gnoblin.snapshot</code></a> — inspect a copy of the current config.</li><li><a href="/gnoblin/config/array"><code>gnoblin.array</code></a> — mark a Lua table as a list.</li><li><a href="/gnoblin/config/lua-events"><code>gnoblin.on</code></a> — handle compositor and input events.</li></ul><p>The named views <a href="/gnoblin/config/configure/shortcuts"><code>gnoblin.configure.shortcuts</code></a> and <a href="/gnoblin/config/configure/autostart"><code>gnoblin.configure.autostart</code></a> read or update entries by name. See the <a href="/gnoblin/guides/shortcuts">shortcuts</a> and <a href="/gnoblin/guides/autostart">autostart</a> guides. Lua&#39;s <code>require</code> loader is covered under <a href="/gnoblin/config/load"><code>gnoblin.load</code></a>.</p><p>For older configs, <code>gnoblin.set</code>, <code>gnoblin.shortcut</code>, <code>gnoblin.autostart</code>, <code>gnoblin.remove_shortcut</code> and <code>gnoblin.remove_autostart</code> remain available but are deprecated. Use <code>gnoblin.configure</code> and its named views; set an imported entry&#39;s <code>enable</code> field to <code>false</code> to disable it.</p><h2 id="first-config" tabindex="-1">First config <a class="header-anchor" href="#first-config" aria-label="Permalink to &quot;First config&quot;">​</a></h2><p>On first login, <code>gnoblin-session</code> copies the packaged reference config to <code>~/.config/gnoblin/init.lua</code> when that file does not exist. It does not replace an existing config. Edit that file to configure Gnoblin.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gnoblinctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gnoblinctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span></code></pre></div><p>See <a href="/gnoblin/recipes/">configuration recipes</a> for complete examples and the <a href="/gnoblin/guides/window_rules">guides</a> for task-based instructions.</p>`,10)])])}const p=n(t,[["render",s]]);export{h as __pageData,p as default};
